/**
 * Settings and secrets read from the Worker's environment.
 *
 * `Env` (the D1 binding) is generated by `wrangler types`. Everything below is
 * set in the Cloudflare dashboard (Worker → Settings → Variables and Secrets)
 * and is optional at the type level because any of it may be missing.
 */
export interface Settings {
  // ── Platform ────────────────────────────────────────────────────────────────
  /** Secret for the platform owner. Sent as the `x-admin-key` header. */
  ADMIN_API_KEY?: string;
  /** Passphrase used to encrypt creators' bot tokens and payment keys in D1. */
  ENCRYPTION_KEY?: string;
  /** Public URL of this Worker. Defaults to the URL the request came in on. */
  APP_URL?: string;
  /** Comma-separated browser origins allowed to call the API. */
  CORS_ORIGINS?: string;
  /** Set to "false" to close public signup. */
  ALLOW_SIGNUPS?: string;
  /** Name shown on the public pages. Defaults to "Paywall Bot". */
  PLATFORM_NAME?: string;
  /** How creators reach you to upgrade, e.g. "@yourname on Telegram" or an email. */
  SUPPORT_CONTACT?: string;
  /** Most signups allowed from one IP address per hour. Default 20; "0" turns the cap off. */
  SIGNUP_LIMIT_PER_HOUR?: string;
  /** Where platform alerts go (Telegram chat IDs). Defaults to ADMIN_USER_IDS. */
  ALERT_CHAT_ID?: string;
  /** "off" stops all Telegram alerts. */
  ALERTS?: string;
  /** Unpaid platform fees (USD) at which a creator's sales pause until they pay. Unset = never. */
  FEE_LIMIT_USD?: string;
  /** Username of a public bot showing what members see (e.g. "PaywallPreviewBot"). Adds a homepage button. */
  PREVIEW_BOT_USERNAME?: string;
  /** Price (USD) of 30 days of the Starter plan, bought in the dashboard. Unset = upgrades by contacting you. */
  STARTER_PRICE_USD?: string;

  // ── Owner bot (same names as the original Python deployment) ────────────────
  TELEGRAM_BOT_TOKEN?: string;
  GROUP_CHAT_ID?: string;
  ADMIN_USER_IDS?: string;
  ONE_TIME_PRICE_USD?: string;
  MONTHLY_PRICE_USD?: string;
  IMAGE_UNLOCK_PRICE_USD?: string;

  NOWPAYMENTS_API_KEY?: string;
  NOWPAYMENTS_IPN_SECRET?: string;

  BTCPAY_URL?: string;
  BTCPAY_STORE_ID?: string;
  BTCPAY_API_KEY?: string;
  BTCPAY_WEBHOOK_SECRET?: string;
  /** "false" = wait for on-chain confirmations before unlocking. Default "true". */
  BTCPAY_ACCEPT_UNCONFIRMED?: string;

  PAYSTACK_SECRET_KEY?: string;
  PAYSTACK_PUBLIC_KEY?: string;
  /** Currency Paystack charges in. Default KES, as in the original bot. */
  PAYSTACK_CURRENCY?: string;
  /** Units of PAYSTACK_CURRENCY per 1 USD. Default 129 for KES, 1 for USD. */
  PAYSTACK_FX_RATE?: string;
  /** Comma-separated Paystack channels. Default "card,mobile_money,bank". */
  PAYSTACK_CHANNELS?: string;
}

export type AppEnv = Env & Settings;

/** The built-in bot and tenant that are configured through Worker secrets. */
export const OWNER_ID = "owner";

export const FREE_TRIAL_DAYS = 14;
export const FREE_MEMBER_LIMIT = 10;
export const FREE_BOT_LIMIT = 1;
export const MONTHLY_ACCESS_DAYS = 30;
/** Length of a self-serve Starter plan period. */
export const PLAN_DAYS = 30;
export const MAX_VAULT_IMAGES = 100;

export const TIER_CUT: Record<string, number> = {
  free: 0.15,
  starter: 0.08,
  whitelabel: 0,
};
